#pragma once
namespace snuw {
inline int entityFieldsTest(const fs::path& folder,const std::string& base){try{
 LoadLibraryW(L"Msftedit.dll");INITCOMMONCONTROLSEX init{sizeof init,ICC_STANDARD_CLASSES};InitCommonControlsEx(&init);auto store=std::make_shared<Store>(folder/"state");store->load();store->useWorkspace(std::string(64,'a'));App app(store);auto parent=CreateWindowExW(0,L"STATIC",L"",0,0,0,900,800,nullptr,nullptr,GetModuleHandle(nullptr),nullptr);if(!parent)throw std::runtime_error("Hidden parent failed");app.hwnd=parent;app.page=7;app.consistencyView=1;app.accountProfile={{"role","develop"}};
 auto identity=std::string(32,'a')+" | Identity";app.learningProfiles=json::array({{{"id",std::string(32,'a')},{"name","Identity"},{"kind","character"}}});store->settings.update({{"api",base},{"api_key","entity-test-key"},{"profile_name","Named Mug"},{"profile_kind","사물 | object"},{"profile_description","ceramic object"},{"profile_pipeline","sdxl"},{"profile_auto_train",true},{"profile_appearance","red ceramic mug"},{"profile_lighting","warm light"},{"consistency_enabled",true},{"consistency_profile",identity}});store->state["drafts"]["prompt"]="landscape";app.entityAttributesOpen=true;app.rebuild(false);
 auto layout=app.learningLayout(app.center(),app.card());size_t features=0;for(auto& field:layout.inputs){if(field.key=="profile_pipeline"||field.key=="profile_auto_train")throw std::runtime_error("Object training controls visible");for(auto& spec:entityFields)if(field.key==spec.setting)features++;}if(features!=7||entityKind(entityKindLabel("place"))!="place")throw std::runtime_error("Structured fields or kind labels mismatch");
 auto pump=[&]{auto until=std::chrono::steady_clock::now()+std::chrono::seconds(20);while(std::chrono::steady_clock::now()<until){for(auto& event:app.engine->take())if(event.kind=="learning_reply"){if(event.text=="failed")throw std::runtime_error(str(event.data,"message"));app.learningReply(event);}if(!app.learningBusy)return;Sleep(10);}throw std::runtime_error("Entity request timed out");};
 app.createLearningProfile();pump();if(!app.selectedTextEntity()||str(store->settings,"consistency_profile")!=identity||app.profileChoices(false).size()!=2||app.allProfileChoices().size()!=3)throw std::runtime_error("Prompt entity leaked into identity selection");layout=app.learningLayout(app.center(),app.card());bool insert=false;for(auto& action:layout.actions){if(action.id==5||action.id==7||action.id==28)throw std::runtime_error("Object training actions visible");insert|=action.id==35;}if(!insert)throw std::runtime_error("Prompt insert action missing");
 auto profile=app.activeProfile();app.openProfileEditor(app.referenceProfiles.at(profile));for(auto& field:app.fields){if(field.key=="profile_name")SetWindowTextW(field.hwnd,L"Changed Mug");if(field.key=="profile_appearance")SetWindowTextW(field.hwnd,L"blue ceramic mug");}app.saveProfileEdit();pump();if(str(app.referenceProfiles.at(profile)["prompt_slots"],"appearance")!="blue ceramic mug")throw std::runtime_error("Structured edit not reflected");
 app.insertSelectedEntity();if(app.page!=0||str(wirePromptDrafts(store->state),"prompt").find(":Changed Mug:")==std::string::npos)throw std::runtime_error("Name token was not inserted");app.undoPrompt();if(str(wirePromptDrafts(store->state),"prompt").find(":Changed Mug:")!=std::string::npos)throw std::runtime_error("Entity insertion is not undoable");
 app.clearControls();DestroyWindow(parent);app.hwnd=nullptr;atomicWrite(folder/"entity-fields-result.json",json{{"ok",true},{"fields",7},{"prompt_only",true},{"identity_preserved",true},{"edit",true},{"insert_undo",true}}.dump());return 0;
 }catch(const std::exception& e){atomicWrite(folder/"entity-fields-result.json",json{{"ok",false},{"error",e.what()}}.dump());return 1;}}
}
